CREATE TABLE harvest_batches(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),plot_id integer NOT NULL REFERENCES plots(id),crop text NOT NULL,harvested_on date NOT NULL,received_grams integer NOT NULL CHECK(received_grams>0),balance_grams integer NOT NULL CHECK(balance_grams>=0),reserved_grams integer NOT NULL DEFAULT 0 CHECK(reserved_grams>=0),verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(balance_grams<=received_grams),CHECK(reserved_grams<=balance_grams));
CREATE TABLE stock_events(id uuid PRIMARY KEY,batch_id uuid NOT NULL REFERENCES harvest_batches(id),actor_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('received','reserve','release','ship','writeoff')),grams integer NOT NULL CHECK(grams>0),reason text NOT NULL,request_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,request_key));
